import type { Page } from '@playwright/test';
import { test, expect, parseAll, clipboard, CHROME_BASH, GARBAGE, INSECURE_GET, SECRETS, SIMPLE_GET, SIMPLE_POST, XML_PUT } from './support/live';

/** Batch editor and Generate All, with every request parsed and generated by the real backend. */

const DELETE_ITEM = `curl -X DELETE "https://api.example.com/items/7" -H "Authorization: Bearer ${SECRETS.bearer}"`;

const sidebar = (page: Page) => page.getByRole('list', { name: 'Requests' });
const row = (page: Page, name: string) => sidebar(page).getByRole('button', { name, exact: true });
const panel = (page: Page) => page.getByTestId('batch-editor-panel');
/** Only the visible editor (editors of other requests stay mounted, hidden). */
const visible = (page: Page, text: string) => panel(page).getByText(text, { exact: true }).filter({ visible: true });

async function removeRequest(page: Page, name: string) {
  await row(page, name).hover();
  await page.getByRole('button', { name: `Remove ${name}` }).click();
}

async function editVisible(page: Page, label: string, value: string) {
  await panel(page).getByRole('button', { name: `Edit ${label}`, exact: true }).filter({ visible: true }).first().click();
  await panel(page).getByRole('textbox', { name: `Value of ${label}`, exact: true }).filter({ visible: true }).fill(value);
  await panel(page).getByRole('button', { name: `Save ${label}`, exact: true }).filter({ visible: true }).click();
}

async function openGenerateAll(page: Page) {
  await page.getByRole('button', { name: 'Generate All' }).click();
  const dialog = page.getByRole('dialog');
  await expect(dialog.getByRole('heading', { name: /^Generate Code for \d+ Requests?$/ })).toBeVisible();
  return dialog;
}

async function runGenerateAll(page: Page) {
  const dialog = page.getByRole('dialog');
  await dialog.getByRole('button', { name: 'Generate All' }).click();
  await expect(dialog.getByRole('heading', { name: 'Generated Batch Code' })).toBeVisible({ timeout: 60_000 });
  return (await dialog.locator('pre').first().innerText()).replace(/\u00a0/g, ' ');
}

test.describe('Batch editor', () => {
  test('[BE-01][BE-16] the parsed requests are listed by method and path; the first is open', async ({ page }) => {
    await parseAll(page, [SIMPLE_GET, SIMPLE_POST, DELETE_ITEM]);
    await expect(page).toHaveURL(/\/batch-editor$/);
    await expect(page.getByRole('heading', { level: 1, name: 'Batch Editor' })).toBeFocused();
    await expect(sidebar(page).getByRole('listitem')).toHaveCount(3);
    await expect(row(page, 'GET /users/42')).toHaveAttribute('aria-current', 'true');
    await expect(visible(page, '/users/42')).toBeVisible();
    await expect(page.getByRole('alert')).toHaveCount(0);

    await page.getByRole('button', { name: 'Back to Playground' }).click();
    await expect(page).toHaveURL(/\/playground$/);
  });

  test('[BE-02] switching requests shows each one; edits survive switching and mark the request', async ({ page }) => {
    await parseAll(page, [SIMPLE_GET, SIMPLE_POST]);
    await row(page, 'POST /users').click();
    await expect(row(page, 'POST /users')).toHaveAttribute('aria-current', 'true');
    await expect(visible(page, '"asha@example.com"')).toBeVisible();
    await expect(visible(page, '/users/42')).toHaveCount(0);

    await editVisible(page, 'endpoint', '/v2/users');
    await expect(row(page, 'POST /v2/users')).toBeVisible();
    await expect(sidebar(page).locator('[title="Edited"]')).toHaveCount(1);
    await row(page, 'GET /users/42').click();
    await row(page, 'POST /v2/users').click();
    await expect(visible(page, '/v2/users')).toBeVisible();
  });

  test('[BE-03][BE-04][PM-03] a command the backend rejects is reported, masked, and can be fixed and retried', async ({ page }) => {
    const bad = `curl -H "Authorization: Bearer ${SECRETS.bearer}" ${GARBAGE}`;
    await parseAll(page, [SIMPLE_GET, bad, SIMPLE_POST]);
    await expect(page).toHaveURL(/\/batch-editor$/);
    await expect(sidebar(page).getByRole('listitem')).toHaveCount(2);
    const alert = page.getByRole('alert').filter({ hasText: 'could not be parsed' });
    await expect(alert).toContainText('1 command could not be parsed and was left out of this batch.');
    await expect(alert).toContainText('Command 2');
    await expect(page.getByTestId('parse-failure-snippet')).toContainText('curl -H');
    await expect(alert).not.toContainText(SECRETS.bearer);

    await page.getByRole('button', { name: 'Edit and retry command 2' }).click();
    const box = page.getByRole('textbox', { name: 'cURL for command 2' });
    await box.fill('still not a curl');
    await page.getByRole('button', { name: 'Retry command 2' }).click();
    await expect(alert).toContainText(/No URL found|URL/);
    await box.fill(XML_PUT);
    await page.getByRole('button', { name: 'Retry command 2' }).click();
    await expect(page.getByText('Command 2 parsed and added to the batch')).toBeVisible();
    await expect(row(page, 'PUT /users/123')).toBeVisible();
    await expect(sidebar(page).getByRole('listitem')).toHaveCount(3);
    await expect(alert).toHaveCount(0);
  });

  test('[BE-04] the failure banner can be dismissed', async ({ page }) => {
    await parseAll(page, [SIMPLE_GET, GARBAGE]);
    await page.getByRole('button', { name: 'Dismiss parse errors' }).click();
    await expect(page.getByRole('alert')).toHaveCount(0);
    await expect(sidebar(page).getByRole('listitem')).toHaveCount(1);
  });

  test('[BE-05][BE-15] remove + Undo; removing the last request shows the empty state', async ({ page }) => {
    await parseAll(page, [SIMPLE_GET, SIMPLE_POST, DELETE_ITEM]);
    await removeRequest(page, 'POST /users');
    await expect(sidebar(page).getByRole('listitem')).toHaveCount(2);
    await page.locator('[data-sonner-toast]').filter({ hasText: 'Removed POST /users' }).getByRole('button', { name: 'Undo' }).click();
    await expect(sidebar(page).getByRole('listitem')).toHaveCount(3);
    await expect(sidebar(page).getByRole('listitem').nth(1)).toContainText('/users');

    for (const name of ['GET /users/42', 'POST /users', 'DELETE /items/7']) await removeRequest(page, name);
    await expect(page.getByRole('heading', { name: 'No Requests' })).toBeVisible();
    await page.getByRole('button', { name: 'Go to Playground' }).click();
    await expect(page).toHaveURL(/\/playground$/);
  });

  test('[BE-12] leaving with edits asks first', async ({ page }) => {
    await parseAll(page, [SIMPLE_GET, SIMPLE_POST]);
    await editVisible(page, 'endpoint', '/users/43');
    await page.getByRole('button', { name: 'Back to Playground' }).click();
    const guard = page.getByRole('dialog', { name: 'Discard unsaved edits?' });
    await guard.getByRole('button', { name: 'Keep editing' }).click();
    await expect(page).toHaveURL(/\/batch-editor$/);
    await page.getByRole('button', { name: 'Back to Playground' }).click();
    await guard.getByRole('button', { name: 'Discard and leave' }).click();
    await expect(page).toHaveURL(/\/playground$/);
  });

  test('[BE-13] history keeps only a redacted batch; after a reload Generate All waits for the secrets', async ({ page }) => {
    await parseAll(page, [CHROME_BASH, DELETE_ITEM]);
    await expect.poll(() => page.evaluate(() => JSON.stringify(window.history.state))).toContain('[REDACTED]');
    const history = await page.evaluate(() => JSON.stringify(window.history.state) + JSON.stringify({ ...sessionStorage }) + JSON.stringify({ ...localStorage }));
    for (const s of [SECRETS.bearer, SECRETS.cookie]) expect(history).not.toContain(s);
    await expect(page.getByRole('button', { name: 'Generate All' })).toBeEnabled();

    await page.reload();
    await expect(page.getByRole('heading', { level: 1, name: 'Batch Editor' })).toBeVisible();
    await expect(page.getByRole('button', { name: 'Generate All' })).toBeDisabled();
    await expect(page.getByRole('status').filter({ hasText: /Re-enter \d+ redacted values? to generate code\./ })).toBeVisible();
    await expect(page.locator('body')).not.toContainText(SECRETS.bearer);
  });
});

test.describe('Generate All', () => {
  test('[BE-06][BE-08] one class with a method per request, unique names and per-method status from the real generator', async ({ page, api }) => {
    await parseAll(page, [SIMPLE_GET, SIMPLE_GET, SIMPLE_POST, DELETE_ITEM]);
    const dialog = await openGenerateAll(page);
    await expect(dialog.getByLabel('Test Class Name')).toHaveValue('BatchApiTest');
    const methods = dialog.getByRole('textbox', { name: /^Method name for / });
    await expect(methods).toHaveCount(4);
    const names = await methods.evaluateAll((els) => els.map((e) => (e as HTMLInputElement).value));
    expect(new Set(names).size).toBe(4);
    expect(names[1]).toBe(`${names[0]}_2`);
    const statuses = dialog.getByRole('spinbutton', { name: /^Expected status for / });
    expect(await statuses.evaluateAll((els) => els.map((e) => (e as HTMLInputElement).value))).toEqual(['200', '200', '201', '204']);
    await statuses.nth(3).fill('202');
    await dialog.getByLabel('Test Class Name').fill('ShopRegressionTest');

    const code = await runGenerateAll(page);
    await api.settle();
    const calls = api.of('/api/generate-from-parsed');
    expect(calls).toHaveLength(4);
    expect(calls.map((c) => (c.body as { config: { statusCode: string; option: string } }).config.statusCode)).toEqual(['200', '200', '201', '202']);
    expect(calls.every((c) => c.status === 200)).toBe(true);

    expect(code).toMatch(/^import /m);
    expect(code).toContain('public class ShopRegressionTest {');
    expect(code.match(/public class /g)).toHaveLength(1);
    for (const name of names) expect(code).toContain(`public void ${name}()`);
    expect(code.match(/@Test/g)!.length).toBe(4);
    expect(code).toContain('/users/42');
    expect(code).toContain('/items/7');
    expect(code).toContain('Assert.assertEquals(statusCode, 201');
    expect(code).toContain('Assert.assertEquals(statusCode, 202');
    // Imports are de-duplicated.
    const imports = code.split('\n').filter((l) => l.startsWith('import '));
    expect(new Set(imports).size).toBe(imports.length);
  });

  test('[BE-07] invalid or duplicate names and an out-of-range status block Generate All', async ({ page }) => {
    await parseAll(page, [SIMPLE_GET, SIMPLE_POST]);
    const dialog = await openGenerateAll(page);
    const go = dialog.getByRole('button', { name: 'Generate All' });
    await dialog.getByLabel('Test Class Name').fill('9Lives');
    await expect(go).toBeDisabled();
    await dialog.getByLabel('Test Class Name').fill('Lives');
    await expect(go).toBeEnabled();
    await dialog.getByRole('textbox', { name: 'Method name for GET /users/42' }).fill('same');
    await dialog.getByRole('textbox', { name: 'Method name for POST /users' }).fill('same');
    await expect(dialog).toContainText('Already used by another request');
    await expect(go).toBeDisabled();
    await dialog.getByRole('textbox', { name: 'Method name for POST /users' }).fill('create user');
    await expect(go).toBeDisabled();
    await dialog.getByRole('textbox', { name: 'Method name for POST /users' }).fill('createUser');
    await dialog.getByRole('spinbutton', { name: 'Expected status for POST /users' }).fill('600');
    await expect(go).toBeDisabled();
    await dialog.getByRole('spinbutton', { name: 'Expected status for POST /users' }).fill('201');
    await expect(go).toBeEnabled();
  });

  test('[BE-11] a request the generator rejects is reported; the others are still generated', async ({ page, api }) => {
    await parseAll(page, [SIMPLE_GET, SIMPLE_POST]);
    const dialog = await openGenerateAll(page);
    // The frontend accepts a Java keyword as a method name; the backend refuses it (a realistic per-request failure).
    await dialog.getByRole('textbox', { name: 'Method name for POST /users' }).fill('switch');
    await dialog.getByRole('button', { name: 'Generate All' }).click();
    await expect(dialog.getByRole('heading', { name: 'Generated Batch Code' })).toBeVisible({ timeout: 60_000 });
    const alert = dialog.getByRole('alert');
    await expect(alert).toContainText('Code could not be generated for 1 of 2 requests.');
    await expect(alert).toContainText(/POST \/users: .*keyword/i);
    const code = await dialog.locator('pre').first().innerText();
    expect(code).toContain('/users/42');
    expect(code).not.toContain('public void switch()');
    await api.settle();
    expect(api.of('/api/generate-from-parsed').map((c) => c.status)).toEqual([200, 422]);
  });

  test('[BE-11] when every request is rejected, an error is shown instead of a result', async ({ page }) => {
    await parseAll(page, [SIMPLE_GET, SIMPLE_POST]);
    const dialog = await openGenerateAll(page);
    await dialog.getByRole('textbox', { name: 'Method name for GET /users/42' }).fill('class');
    await dialog.getByRole('textbox', { name: 'Method name for POST /users' }).fill('switch');
    await dialog.getByRole('button', { name: 'Generate All' }).click();
    await expect(dialog.getByRole('alert')).toContainText('Code generation failed for all 2 requests.', { timeout: 60_000 });
    await expect(dialog.getByRole('heading', { name: 'Generated Batch Code' })).toHaveCount(0);
  });

  test('[BE-10] Copy redacts every request\'s secrets unless unticked', async ({ page, context }) => {
    await context.grantPermissions(['clipboard-read', 'clipboard-write']);
    await parseAll(page, [CHROME_BASH, DELETE_ITEM]);
    const dialog = await openGenerateAll(page);
    await runGenerateAll(page);
    const redact = dialog.getByRole('checkbox', { name: 'Redact secrets when copying' });
    await expect(redact).toBeChecked();
    await dialog.getByRole('button', { name: 'Copy' }).click();
    const safe = await clipboard(page);
    expect(safe).toContain('public class BatchApiTest');
    expect(safe).not.toContain(SECRETS.bearer);
    expect(safe).not.toContain(SECRETS.cookie);
    await redact.click();
    await dialog.getByRole('button', { name: /Copy/ }).click();
    await expect.poll(() => clipboard(page)).toContain(SECRETS.bearer);

    await dialog.getByRole('button', { name: 'Back to Config' }).click();
    await expect(dialog.getByRole('heading', { name: /^Generate Code for 2 Requests$/ })).toBeVisible();
  });

  test('[BE-09] relaxed HTTPS only for the request that used -k (BUG-E2E-10)', async ({ page }) => {
    test.fail(true, 'BUG-E2E-10: the backend reports -k as ssl_config.basic.insecure, which isInsecureCurl does not read; the merged method loses relaxed HTTPS');
    await parseAll(page, [SIMPLE_GET, INSECURE_GET]);
    await openGenerateAll(page);
    const code = await runGenerateAll(page);
    const start = code.indexOf('public void testGet_status');
    expect(start).toBeGreaterThan(-1);
    expect(code.slice(0, start)).not.toContain('relaxedHTTPSValidation');
    expect(code.slice(start)).toContain('relaxedHTTPSValidation');
  });

  test.describe('at 390px', () => {
    test.use({ viewport: { width: 390, height: 844 }, hasTouch: true, isMobile: true });

    test('[BE-14] the list becomes a selector; the editor keeps the width; remove works', async ({ page }) => {
      await parseAll(page, [SIMPLE_GET, SIMPLE_POST, DELETE_ITEM]);
      await expect(sidebar(page)).toBeHidden();
      const select = page.getByRole('combobox', { name: 'Request' });
      await select.selectOption({ label: 'POST /users' });
      await expect(visible(page, '"asha@example.com"')).toBeVisible();
      const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
      expect(overflow).toBeLessThanOrEqual(0);
      await page.getByRole('button', { name: 'Remove selected request' }).click();
      await expect(select.locator('option')).toHaveCount(2);
    });
  });
});
